import { DataGrid } from "march/components/data-grid"
import { Card } from "march/ui"

// bir mağazanın sipariş paneli: 5 000 sipariş, bölgeye göre gruplu, adet hücresi düzenlenir, seçim sayılır
const REGIONS = ["Marmara", "Ege", "Akdeniz", "Karadeniz"]
const PRODUCTS = ["Defter", "Kalem", "Çanta", "Lamba", "Klavye"]
type Order = { id: number; customer: string; region: string; product: string; qty: number; price: number }
const make = (): Order[] => Array.from({ length: 5000 }, (_, i) => ({
  id: i + 1, customer: `Müşteri ${1 + ((i * 37) % 400)}`, region: REGIONS[i % REGIONS.length]!,
  product: PRODUCTS[(i * 7) % PRODUCTS.length]!, qty: 1 + ((i * 13) % 20), price: 20 + ((i * 53) % 480),
}))

export function OrderGrid() {
  let $orders = make()
  let $last = "Bir Adet hücresine çift tıklayıp düzenleyin"
  const save = (row: Order, key: string, value: unknown) => {
    $orders = $orders.map((o) => (o.id === row.id ? { ...o, [key]: Number(value) } : o))
    $last = `#${row.id} güncellendi: ${key} = ${String(value)}`
  }
  return <Card title="Siparişler" subtitle={() => $last}>
    <DataGrid label="Siparişler" rows={() => $orders} rowKey="id" height={420} selectable groupBy={["region"]} filename="siparisler"
      labels={{ search: "Sipariş ara", rows: (n: string) => `${n} sipariş`, total: "Genel toplam" }}
      onEdit={save}
      columns={[
        { key: "id", label: "No", width: 80, type: "number" },
        { key: "customer", label: "Müşteri", width: 160, filter: "text" },
        { key: "region", label: "Bölge", width: 130, filter: "select", options: REGIONS },
        { key: "product", label: "Ürün", width: 130, filter: "select", options: PRODUCTS },
        { key: "qty", label: "Adet", width: 100, type: "number", editable: true, aggregate: "sum",
          validate: (v: unknown) => (Number(v) > 0 ? null : "En az 1") },
        { key: "total", label: "Tutar", width: 140, value: (r: Order) => r.qty * r.price, format: ["money", "TRY"], aggregate: "sum" },
      ]} />
  </Card>
}

import { DataGrid } from "march/components/data-grid"
import { Empty, Button } from "march/ui"

// DataGrid'in bütün özellikleri bir arada: rows, columns, rowKey, height, rowHeight, groupBy + onGroupBy (denetimli),
// selectable, onEdit, footer, toolbar (tek tek araçlar), columnMenu, empty, labels, animate, filename, onActivate,
// label, class. (table: march/table'daki createTable() durumunu alır; önizlemede o paket yok.)
type Task = { code: string; title: string; team: string; points: number; done: boolean }
const tasks: Task[] = [
  { code: "M-1", title: "Giriş sayfası", team: "Web", points: 5, done: true },
  { code: "M-2", title: "Ödeme akışı", team: "Web", points: 8, done: false },
  { code: "M-3", title: "Bildirimler", team: "Mobil", points: 3, done: false },
  { code: "M-4", title: "Çevrimdışı mod", team: "Mobil", points: 13, done: false },
  { code: "M-5", title: "Rapor servisi", team: "API", points: 5, done: true },
  { code: "M-6", title: "Önbellek", team: "API", points: 2, done: false },
]

export function DataGridLab() {
  let $rows = tasks
  let $group: string[] = []
  let $dense = false
  let $empty = false
  let $opened = "—"
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      <Button size="sm" on:click={() => $group = $group.length ? [] : ["team"]}>{() => ($group.length ? "Gruplamayı kaldır" : "Takıma göre grupla")}</Button>
      <Button size="sm" on:click={() => $dense = !$dense}>{() => ($dense ? "Rahat satırlar" : "Sıkı satırlar")}</Button>
      <Button size="sm" on:click={() => $empty = !$empty}>{() => ($empty ? "Görevleri geri getir" : "Listeyi boşalt")}</Button>
    </div>
    <p sx={{ text: "sm", color: "muted" }}>{() => `Gruplar: ${$group.join(", ") || "yok"} · Açılan: ${$opened}`}</p>
    <DataGrid label="Sprint görevleri" class="lab-grid" filename="sprint" height={340}
      rows={() => ($empty ? [] : $rows)} rowKey={(r: Task) => r.code}
      rowHeight={() => ($dense ? 30 : 40)}
      groupBy={() => $group} onGroupBy={(keys: string[]) => $group = keys}
      selectable footer columnMenu animate
      toolbar={{ search: true, groups: true, filters: true, csv: false, count: true }}
      empty={<Empty title="Görev yok" />}
      labels={{ search: "Görev ara", rows: (n: string) => `${n} görev`, selected: (n: string) => `${n} seçili`, total: "Toplam puan" }}
      onEdit={(row: Task, key: string, value: unknown) => { $rows = $rows.map((r) => (r.code === row.code ? { ...r, [key]: key === "points" ? Number(value) : value } : r)) }}
      onActivate={(row: Task, key: string) => $opened = `${row.code} (${key})`}
      columns={[
        { key: "code", label: "Kod", width: 90, pin: "left" },
        { key: "title", label: "Görev", width: 180, editable: true },
        { key: "team", label: "Takım", width: 110, filter: "select" },
        { key: "points", label: "Puan", width: 100, type: "number", editable: true, aggregate: "sum" },
        { key: "done", label: "Bitti", width: 90, value: (r: Task) => (r.done ? "evet" : "hayır"), aggregate: "count" },
      ]} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { DataGridLab } from "./DataGridLab.tsx"

// DataGridLab'in testleri: kaydedince Testler sekmesinde çalışır
test("ızgara adını ve sınıfını alır", () => {
  const s = renderTest(() => <DataGridLab />)
  expect(s.get("[role=grid]")?.getAttribute("aria-label")).toBe("Sprint görevleri")
  expect(s.get(".lab-grid")).not.toBe(null)
})

test("kendi metinleri: satır sayısı 'görev' ile yazılır", async () => {
  const s = renderTest(() => <DataGridLab />)
  await s.flush()
  expect(s.sees("6 görev")).toBe(true)
})

test("gruplayınca grup satırları eklenir: başlık + 3 grup + 6 satır (aria-rowcount)", async () => {
  const s = renderTest(() => <DataGridLab />)
  expect(s.get("[role=grid]")?.getAttribute("aria-rowcount")).toBe("7")
  await s.click("Takıma göre grupla")
  await s.flush()
  expect(s.sees("Gruplar: team")).toBe(true)
  expect(s.get("[role=grid]")?.getAttribute("aria-rowcount")).toBe("10")
})

test("liste boşalınca kendi boş ekranı görünür", async () => {
  const s = renderTest(() => <DataGridLab />)
  await s.click("Listeyi boşalt")
  await s.flush()
  expect(s.sees("Görev yok")).toBe(true)
})
